local config = {
  ui_story_32160401_1_dialog_content = "Hei, kita mau makan sesuatu?",
  ui_story_32160401_2_dialog_content = "Ya! Aku sudah memikirkannya dan ini sepertinya cara terbaik untuk berterima kasih padamu.",
  ui_story_32160401_3_dialog_content = "Kalau tidak, aku akan terus memasukkan lebih banyak perangkat kepadamu.",
  ui_story_32160401_4_option_content = "Tidak perlu sama sekali berterima kasih padaku.",
  ui_story_32160401_5_dialog_content = "Aku tidak membantumu demi ucapan terima kasihmu.",
  ui_story_32160401_6_dialog_content = "Tentu saja, aku suka melihat para ahli dari berbagai tempat berkumpul dan berbicara.",
  ui_story_32160401_7_dialog_content = "Karena itulah cara kita memperkenalkan lebih banyak ide baru ke dunia.",
  ui_story_32160401_8_dialog_content = "Itu benar sekali!",
  ui_story_32160401_9_dialog_content = "Tapi aku tetap harus membalas. Tidak melakukannya itu bukan aku.",
  ui_story_32160401_10_option_content = "Lebih banyak gadget tidak selalu buruk...",
  ui_story_32160401_11_dialog_content = "Sebenarnya, aku cukup menyukai mereka...",
  ui_story_32160401_12_dialog_content = "Abaikan saja orang-orang sombong yang menyebut mereka \"sampah tren\"!",
  ui_story_32160401_13_dialog_content = "Anda puas dengan gadget? Um... Baguslah. Itu pengakuan, bukan?",
  ui_story_32160401_14_dialog_content = "Mungkin aku akan memberimu beberapa lagi setelah kita selesai makan...",
  ui_story_32160401_15_dialog_content = "Kamu terlihat seperti tahu satu atau dua hal tentang membuat sesuatu. Bagaimana kalau kita bicara sambil makan?",
  ui_story_32160401_16_dialog_content = "Tentu, saya ingin mendengar pendapat Anda tentang keterampilan kerajinan Longzhou.",
  ui_story_32160401_17_dialog_content = "Jadi, bagaimana makanan di sini?",
  ui_story_32160401_18_dialog_content = "Luar biasa! Tak pernah kusangka jajanan pinggir jalan bisa selezat ini.",
  ui_story_32160401_19_dialog_content = "Kamu bilang kamu ingin tempat makan yang dipilih oleh penduduk lokal Longzhou yang sebenarnya...",
  ui_story_32160401_20_dialog_content = "Dan itu berarti sebuah lubang di dinding yang tersembunyi di sebuah gang belakang di suatu tempat.",
  ui_story_32160401_21_dialog_content = "Membuat pelanggan kembali hanya berdasarkan rasa saja adalah ukuran sebenarnya dari rumah makan yang baik!",
  ui_story_32160401_22_dialog_content = "Benar, saya bisa bilang Anda berbicara dari pengalaman.",
  ui_story_32160401_23_dialog_content = "Namun, saya tidak pernah menyangka Anda begitu tertarik dengan topik makanan, Xuan Ji.",
  ui_story_32160401_24_dialog_content = "Aku berencana menggunakan kesempatan ini untuk membahas rahasia-rahasia tentang gawai.",
  ui_story_32160401_25_dialog_content = "Tapi sampai saat ini, yang kita bicarakan hanyalah hot pot dari Longzhou.",
  ui_story_32160401_26_dialog_content = "Ups...",
  ui_story_32160401_27_dialog_content = "Bagaimana jika kita mengungkap sedikit tentang \"Cara Pengrajin\"?",
  ui_story_32160401_28_dialog_content = "Yah, sebenarnya aku tidak sepenuhnya melantur.",
  ui_story_32160401_29_dialog_content = "Siapa bilang panci dan penggorengan tidak bisa jadi inspirasi?",
  ui_story_32160401_30_dialog_content = "Ini seperti beberapa alat yang telah kita sebutkan sebelumnya...",
  ui_story_32160401_31_dialog_content = "Blazing Bull berbentuk seperti banteng tetapi bisa menyemburkan api, ide yang saya dapatkan dari nyala api panci panas.",
  ui_story_32160401_32_dialog_content = "Naga Penggali memiliki kerangka kalajengking dengan ekor untuk membantu orang menggali terowongan, yang berasal dari cerobong asap panci panas.",
  ui_story_32160401_33_dialog_content = "Whirlwind Harrier bisa mendarat dengan bebas bahkan tanpa angin... Uap panas dari hot pot menyediakan percikan yang dibutuhkan.",
  ui_story_32160401_34_dialog_content = "Lebih berguna makan hot pot daripada yang kamu kira!",
  ui_story_32160401_35_dialog_content = "Hei, itu curang. Kamu pasti mengada-ada!",
  ui_story_32160401_36_dialog_content = "Ini hanya hot pot. Bagaimana kamu bisa mendapatkan begitu banyak ide desain darinya?",
  ui_story_32160401_37_dialog_content = "Kenapa kamu tidak mencoba dan cari tahu sendiri?",
  ui_story_32160401_38_dialog_content = "Untuk memulai, mari kita katakan kita ingin hot pot di depan kita ini dipanaskan lebih cepat...",
  ui_story_32160401_39_dialog_content = "Berapa cara yang bisa kita lakukan untuk mewujudkannya?",
  ui_story_32160401_40_option_content = "Apa? Apakah kamu menggoda aku?",
  ui_story_32160401_41_dialog_content = "Tidak, saya lebih suka memanggang daging sapi.",
  ui_story_32160401_42_dialog_content = "Anggap saja ini sebagai latihan untuk kamu akhirnya makan hot pot sendirian.",
  ui_story_32160401_43_option_content = "Aku bukan pengrajin jadi mana kutahu",
  ui_story_32160401_44_dialog_content = "Tidak apa-apa hanya menebak saja.",
  ui_story_32160401_45_dialog_content = "Kita hanya sedang berdiskusi, bukan mencari jawaban yang benar.",
  ui_story_32160401_46_dialog_content = "Nah... Tambahkan lebih banyak bahan bakar? Membuat panci lebih tebal agar panasnya tertahan? Beralih ke kompor dengan material yang lebih baik?",
  ui_story_32160401_47_dialog_content = "Bagus! Semua yang kamu sebutkan...",
  ui_story_32160401_48_dialog_content = "Cukup untuk memulai merancang alat Flame Force.",
  ui_story_32160401_49_dialog_content = "Alat Flame Force... Banteng Berkobar?",
  ui_story_32160401_50_dialog_content = "Benar.",
  ui_story_32160401_51_dialog_content = "Seperti perut sapi, wadah ini dapat menyimpan lebih banyak bahan bakar dengan kualitas interior yang baik dan lapisan tipis untuk menghilangkan panas dengan cepat...",
  ui_story_32160401_52_dialog_content = "Pada akhirnya, mengarah pada Clockwork Beast yang menyimpan banyak Flame Force cadangan dan dapat memanas secara instan.",
  ui_story_32160401_53_dialog_content = "Hei, kompor ini sudah panas dengan sempurna, tepat waktu ya.",
  ui_story_32160401_54_dialog_content = "Ini makanan yang dipesan kalian berdua. Selamat menikmati!",
  ui_story_32160401_55_dialog_content = "Trims!",
  ui_story_32160401_56_dialog_content = "Jadi, kamu berhasil mengerti \"Cara Pengrajin\" dari hot pot, kan?",
  ui_story_32160401_57_dialog_content = "Coba sekarang jenis makanan baru ini selagi masih panas!",
  ui_story_32160401_58_dialog_content = "Aku masih merasa agak bingung...",
  ui_story_32160401_59_dialog_content = "Kenapa? Ini bukan seleramu, ya?",
  ui_story_32160401_60_dialog_content = "Tidak, saya sedang memikirkan apa yang Anda katakan di kepala saya.",
  ui_story_32160401_61_dialog_content = "Kamu melewatkan hal-hal penting, bukan?",
  ui_story_32160401_62_dialog_content = "Jika kamu benar-benar bisa merasakan sesuatu yang begitu misterius dari benda-benda biasa...",
  ui_story_32160401_63_dialog_content = "Tidakkah akan ada lebih banyak pengrajin daripada koki, mengingat jumlah penduduk di Longzhou?",
  ui_story_32160401_64_dialog_content = "Huek...",
  ui_story_32160401_65_dialog_content = "Hahaha...!",
  ui_story_32160401_66_dialog_content = "Jangan tertawa lagi!",
  ui_story_32160401_67_dialog_content = "Aku tahu maksudmu:",
  ui_story_32160401_68_dialog_content = "Seniman jenius dapat mendapatkan inspirasi dari apa saja.",
  ui_story_32160401_69_dialog_content = "Saya setuju itu memang benar, tapi saya tidak berpikir itu kuncinya.",
  ui_story_32160401_70_dialog_content = "Tidak, sebenarnya justru sebaliknya.",
  ui_story_32160401_71_dialog_content = "Mengenai perangkat gadget...",
  ui_story_32160401_72_dialog_content = "Hanya mereka yang bisa terinspirasi oleh hal lain selain gadget yang dapat menjadi seniman jenius.",
  ui_story_32160401_73_dialog_content = "Kebijaksanaan sejati terletak pada segala hal dan alam. Kita hanya mengaplikasikannya pada perangkat.",
  ui_story_32160401_74_dialog_content = "Kurasa aku mengerti, tapi tidak begitu yakin...",
  ui_story_32160401_75_dialog_content = "Berbicara tentang alam, mengapa begitu banyak perangkat yang memiliki bentuk seperti hewan?",
  ui_story_32160401_76_dialog_content = "Pertanyaan bagus.",
  ui_story_32160401_77_dialog_content = "Qianyun, aliran keahlian saya, percaya:",
  ui_story_32160401_78_dialog_content = "Tidak peduli seberapa rumit sebuah gadget, itu tidak ada apa-apanya dibandingkan dengan karya alam.",
  ui_story_32160401_79_dialog_content = "Bentuk dan kekuatan dari segala sesuatu serta bagaimana mereka mencapai Lumina merupakan hasil dari ribuan tahun proses bertahan hidup.",
  ui_story_32160401_80_dialog_content = "Itulah yang paling cocok untuk mereka saat ini.",
  ui_story_32160401_81_dialog_content = "Jadi, Qianyun percaya bahwa meniru hewan adalah meniru alam. Itulah jalan yang benar.",
  ui_story_32160401_82_dialog_content = "Tentu saja, kamu tidak meniru penampilan mereka, tetapi cara mereka berfungsi.",
  ui_story_32160401_83_dialog_content = "Misalnya, membuat sesuatu yang bisa memanjat pohon.",
  ui_story_32160401_84_dialog_content = "Kuncinya bukan membuatnya terlihat seperti monyet, tetapi bagaimana cara kerja anggota tubuh monyet.",
  ui_story_32160401_85_dialog_content = "Lihat cara mereka bergerak, tiru cara mereka bertindak, dan akhirnya dapatkan hasil yang Anda inginkan.",
  ui_story_32160401_86_dialog_content = "Aku mengerti... Sepertinya ini berkaitan dengan teori simulacrum yang muncul dari beberapa lab Illumina.",
  ui_story_32160401_87_dialog_content = "Mendekati, meskipun pengrajin di Longzhou telah mengerjakannya selama ribuan tahun.",
  ui_story_32160401_88_dialog_content = "Saya rasa itu salah satu alasan mengapa kedua belah pihak bergerak ke arah yang berbeda.",
  ui_story_32160401_89_dialog_content = "Ya, sekarang aku jauh lebih jelas.",
  ui_story_32160401_90_dialog_content = "Bagaimana dengan gadget yang tidak terlihat seperti hewan? Seperti...",
  ui_story_32160401_91_dialog_content = "Seperti Payung Aneh itu?",
  ui_story_32160401_92_dialog_content = "Ya!",
  ui_story_32160401_93_dialog_content = "Nah, itu karena prinsip di baliknya melibatkan lebih dari sekadar sekolah desain Qianyun...",
  ui_story_32160401_94_dialog_content = "Tapi cara Dikun juga.",
  ui_story_32160401_95_dialog_content = "Dikun sangat berbeda dari Qianyun.",
  ui_story_32160401_96_dialog_content = "Mereka percaya bahwa semua hal yang tumbuh secara alami pada dasarnya memiliki kekurangan.",
  ui_story_32160401_97_dialog_content = "Makhluk yang berenang di laut mati saat berada di luar air. Makhluk terbang sangat rapuh. Makhluk darat terikat di daratan.",
  ui_story_32160401_98_dialog_content = "Hanya ciptaan buatan yang bisa bebas dari cacat. Hanya kita yang bisa mewujudkan kesempurnaan.",
  ui_story_32160401_99_dialog_content = "Dan karena Anda tidak perlu mengacaukan kesempurnaan, itu pasti benda mati.",
  ui_story_32160401_100_dialog_content = "Inilah mengapa mereka tidak menganut cara lama dalam membuat ciptaan mereka menyerupai hewan.",
  ui_story_32160401_101_dialog_content = "Jadi mereka cenderung membuat terutama jebakan dan alat pasif, kemudian menambahkan mesiu ke dalam campuran.",
  ui_story_32160401_102_dialog_content = "Kamu tidak terdengar seperti menentang Dikun, ya?",
  ui_story_32160401_103_dialog_content = "Mengapa harus begitu? Itu juga kebijaksanaan dari semua pengrajin sebelum saya lahir.",
  ui_story_32160401_104_dialog_content = "Ini sangat membantu saya, sebanyak hot pot.",
  ui_story_32160401_105_dialog_content = "Jika kamu ingin tahu, saya menentang status quo saat ini antara kedua sekolah tersebut.",
  ui_story_32160401_106_dialog_content = "Mereka bertengkar dan berdebat terus-menerus, semakin menjauh dari seni.",
  ui_story_32160401_107_dialog_content = "Tapi masalahnya: mereka bahkan tidak bertengkar untuk membuat alat yang lebih baik.",
  ui_story_32160401_108_dialog_content = "Sebaliknya, mereka ingin orang mengakui keunggulan mereka, sehingga siswa mereka masing-masing akan terlihat lebih bermartabat di hadapan raja.",
  ui_story_32160401_109_dialog_content = "Pertengkaran seperti itu yang membuat teknik pembuatan gadget di Kerajaan Ye menjadi stagnan...",
  ui_story_32160401_110_dialog_content = "Itulah mengapa saya membuat parasol, hanya untuk membuktikan betapa tidak bergunanya perselisihan mereka.",
  ui_story_32160401_111_dialog_content = "Apakah itu sebabnya itu jadi favoritmu dan kamu membawanya setiap hari?",
  ui_story_32160401_112_dialog_content = "Benar. Ini memiliki pro dari kedua sekolah.",
  ui_story_32160401_113_dialog_content = "Meniru fungsi dan sangat serbaguna. Juga mudah dibawa, seperti beberapa gadget tertentu.",
  ui_story_32160401_114_dialog_content = "Payung ini berisi capung tembaga dan burung mekanik, serta anak panah dan manik-manik.",
  ui_story_32160401_115_dialog_content = "Aktif dan pasif, kedua sekolah ini menjadi satu. Kamu bisa menyebutnya magnum opus saya.",
  ui_story_32160401_116_dialog_content = "Menarik... Itu membuat saya ingin membuat gadget sendiri.",
  ui_story_32160401_117_dialog_content = "Nah, meskipun aku mengakui bakat dan kecerdasanmu...",
  ui_story_32160401_118_dialog_content = "Tidak mudah untuk memulai dari awal tanpa pengalaman sama sekali.",
  ui_story_32160401_119_option_content = "Ajarilah saya, Xuan Ji! Tidak... Master Xuan Ji!",
  ui_story_32160401_120_dialog_content = "Berhenti membuatku kesal! Baiklah, aku bisa menunjukkan sesuatu yang sederhana. Anggap itu sebagai cara aku membalas budi.",
  ui_story_32160401_121_dialog_content = "Jadi kamu tidak akan berpikir bahwa aku hanya pandai membuat panci panas.",
  ui_story_32160401_122_option_content = "Oke. Apa langkah sederhana yang bisa saya lakukan?",
  ui_story_32160401_123_dialog_content = "Biarkan aku berpikir... Ah, aku mengerti.",
  ui_story_32160401_124_dialog_content = "Liontin berbentuk hati yang pernah kubuat sebelumnya. Kita akan mulai dari itu.",
  ui_story_32160401_125_dialog_content = "Liontin berbentuk hati...?",
  ui_story_32160401_126_dialog_content = "Ini adalah mainan teka-teki dari Kerajaan Ye, dengan mekanisme penguncian yang bersilang. Ini adalah alat yang paling sederhana.",
  ui_story_32160401_127_dialog_content = "Tapi, setelah saya mengatasinya, masalah ini bukan lagi sesuatu yang bisa dipecahkan oleh orang biasa.",
  ui_story_32160401_128_dialog_content = "Jadi, saya harus mencari tahu sendiri?",
  ui_story_32160401_129_dialog_content = "Hehe, tenang saja! Coba main-main dengan itu.",
  ui_story_32160401_130_dialog_content = "Setelah kamu cukup bermain dengannya, wawasan akan mulai muncul...",
  ui_story_32160601_1_dialog_content = "Itu seharusnya melengkapi catatan saya!",
  ui_story_32160601_2_dialog_content = "Sekali lagi terima kasih atas bantuan Anda hari ini, PlayerName.",
  ui_story_32160601_3_dialog_content = "Saya tidak menyadari bahwa Colossus bisa memberikan saya pemandangan langit malam yang begitu jernih. Ini sangat membantu.",
  ui_story_32160601_4_dialog_content = "Jangan sebutkan itu. Yang saya lakukan hanyalah menyesuaikan proyeksi sedikit.",
  ui_story_32160601_5_dialog_content = "Selain itu, saya juga menikmati melihatnya.",
  ui_story_32160601_6_dialog_content = "Jadi kamu juga suka melihat bintang-bintang?",
  ui_story_32160601_7_dialog_content = "Ya!",
  ui_story_32160601_8_dialog_content = "Ketika aku masih terkubur di bawah tanah, Soroz akan menunjukkan gambaran dunia luar kepada saya.",
  ui_story_32160601_9_dialog_content = "Tapi ketika akhirnya saya melihat bintang-bintang dengan mata kepala sendiri, saya menyadari betapa jauh sebenarnya mereka...",
  ui_story_32160601_10_dialog_content = "Sejujurnya, itu membuatku merasa sedikit sedih.",
  ui_story_32160601_11_dialog_content = "Tapi, itu tidak bisa diubah, kan? Jadi...",
  ui_story_32160601_12_dialog_content = "Apakah kamu sedang mengembangkan jenis mesin baru dengan semua penelitian ini?",
  ui_story_32160601_13_dialog_content = "Benar! Bagaimanapun, Festival Musim Semi sudah di depan mata.",
  ui_story_32160601_14_dialog_content = "Hah? Apa hubungannya dengan Festival Musim Semi?",
  ui_story_32160601_15_dialog_content = "Ingat bahwa saya belajar di bawah sekte Qianyun?",
  ui_story_32160601_16_dialog_content = "Jika kita tidak sedang mengerjakan sesuatu yang mendesak, murid seperti saya seharusnya mengunjungi guru kami selama Festival Musim Semi.",
  ui_story_32160601_17_dialog_content = "Dengan cara itu, kita bisa memamerkan—maksud saya mendemonstrasikan hasil kerja kita selama setahun itu.",
  ui_story_32160601_18_dialog_content = "Itulah sebabnya setiap kali festival tiba, saya merasa perlu untuk bekerja pada sesuatu yang lebih besar.",
  ui_story_32160601_19_dialog_content = "Kedengarannya menarik.",
  ui_story_32160601_20_dialog_content = "Saya benar-benar ingin melihat-lihat sekte Qianyun suatu hari nanti.",
  ui_story_32160601_21_dialog_content = "Kerajaan Ye, tempat teknologi berkuasa mutlak... Pasti tempat yang sangat istimewa!",
  ui_story_32160601_22_dialog_content = "Tunggu, berbicara tentang Festival Musim Semi... Kamu tidak akan pulang tahun ini, bukan? Apakah itu benar-benar tidak apa-apa?",
  ui_story_32160601_23_dialog_content = "Tidak ada yang bisa saya lakukan tentang itu!",
  ui_story_32160601_24_dialog_content = "Aku ingin mengantarmu kembali dan menunjukkan sekeliling, tapi perjalanannya terlalu lama untuk sampai di sana.",
  ui_story_32160601_25_dialog_content = "Sayang sekali!",
  ui_story_32160601_26_dialog_content = "Namun…",
  ui_story_32160601_27_dialog_content = "Namun?",
  ui_story_32160601_28_dialog_content = "Saya baru saja terpukau oleh inspirasi!",
  ui_story_32160601_29_dialog_content = "Aku akan memberi tahu kamu semua tentang ide-ideku secepatnya, aku janji!",
  ui_story_32160601_30_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian</color>",
  ui_story_32160601_31_dialog_content = "(Surat dari Xuan Ji menyuruh saya untuk datang ke tempat ini.)",
  ui_story_32160601_32_dialog_content = "(Tapi, aku tidak melihat apa pun di sekitar sini.)",
  ui_story_32160601_33_dialog_content = "Klik—",
  ui_story_32160601_34_dialog_content = "Kepiting api? Apa yang sedang dia lakukan di sini?!",
  ui_story_32160601_35_dialog_content = "Klik, klik—",
  ui_story_32160601_36_dialog_content = "Apakah itu memberi tahu saya untuk pergi ke sana?",
  ui_story_32160601_37_dialog_content = "Cuit!",
  ui_story_32160601_38_dialog_content = "Ini menunjuk dengan sayapnya... Ke arah ini, benar?",
  ui_story_32160601_39_dialog_content = "Ngungg—",
  ui_story_32160601_40_dialog_content = "Kemana kau membawaku?!",
  ui_story_32160601_41_dialog_content = "H-Hey, kita tidak bisa begitu saja menerobos masuk ke kamar orang lain—",
  ui_story_32160601_42_dialog_content = "Sebentar, ini...?",
  ui_story_32160601_43_dialog_content = "Oh bagus, kamu membawa PlayerName!",
  ui_story_32160601_44_dialog_content = "Bisakah kamu memberitahu saya apa yang sedang terjadi—",
  ui_story_32160601_45_dialog_content = "Xuan... Ji?",
  ui_story_32160601_46_dialog_content = "Ada apa? Tidak mengenali saya?",
  ui_story_32160601_47_dialog_content = "Tidak, hanya saja gayamu sedikit berbeda dari biasanya hari ini.",
  ui_story_32160601_48_dialog_content = "Ini adalah pakaian tradisional dari murid sekte Qianyun. Nyaman dan praktis, kan?",
  ui_story_32160601_49_dialog_content = "Sayangnya, karena semua orang memakai pakaian yang sama persis, pakaian kita kehilangan sedikit keunikan mereka.",
  ui_story_32160601_50_dialog_content = "Kurasa mereka sangat cocok untukmu, Xuan Ji.",
  ui_story_32160601_51_dialog_content = "Rasanya hampir seperti kamu kembali ke masa sebelum kita saling kenal.",
  ui_story_32160601_52_dialog_content = "Heheh, jika itu yang kamu rasakan, maka aku harus lebih sering mengenakan pakaian ini.",
  ui_story_32160601_53_dialog_content = "Tunggu, jadi apakah itu berarti ruangan ini juga...",
  ui_story_32160601_54_dialog_content = "Benar sekali! Ini adalah replika dari workshop saya di Qianyun!",
  ui_story_32160601_55_dialog_content = "Karena tahun ini saya tidak bisa pulang, saya pikir saya bisa membawa sebagian dari mereka ke sini!",
  ui_story_32160601_56_dialog_content = "Itu masuk akal, kan?",
  ui_story_32160601_57_dialog_content = "Tentu saja... Tunggu, tidak!",
  ui_story_32160601_58_dialog_content = "Ini mungkin terlihat seperti workshopmu, tetapi tidak ada satu pun teman sejawatmu di sini!",
  ui_story_32160601_59_dialog_content = "Bagaimana kamu seharusnya menunjukkan kepada mereka hasil kerjamu selama setahun?",
  ui_story_32160601_60_dialog_content = "Oh, tak masalah buatku.",
  ui_story_32160601_61_dialog_content = "Mengapa menurutmu sangat penting bagi saya untuk membagikan pekerjaan saya dengan orang lain?",
  ui_story_32160601_62_dialog_content = "Nah, mesin bisa sangat rumit, jadi berkumpul bersama orang lain adalah cara yang bagus untuk belajar... Benar, kan?",
  ui_story_32160601_63_dialog_content = "Benar.",
  ui_story_32160601_64_dialog_content = "Dengan kata lain, selama orang bisa saling memahami, mereka juga bisa belajar satu sama lain tanpa memandang sekte atau latar belakang.",
  ui_story_32160601_65_dialog_content = "Lalu…",
  ui_story_32160601_66_dialog_content = "Parasol yang sedang aku kerjakan ini memang bukan untuk mereka dari awal.",
  ui_story_32160601_67_dialog_content = "Dengan meminjam beberapa konsep dari bola armilari dan menyederhanakan struktur mereka, kemudian menerapkan informasi yang diperoleh dari proyeksi bintang Colossus...",
  ui_story_32160601_68_dialog_content = "Aku bisa menciptakan gerakan bintang-bintang dengan payung besar ini.",
  ui_story_32160601_69_option_content = "I-Indahnya!",
  ui_story_32160601_70_dialog_content = "Kalau aku tidak tahu, aku akan mengira ini adalah sebuah karya seni atau semacamnya.",
  ui_story_32160601_71_dialog_content = "Pujian Anda sangat kami hargai!",
  ui_story_32160601_72_option_content = "Lebih dari sekedar indah.",
  ui_story_32160601_73_dialog_content = "... Maafkan saya, Xuan Ji.",
  ui_story_32160601_74_dialog_content = "Hah? Mengapa kau meminta maaf?",
  ui_story_32160601_75_dialog_content = "Saya benar-benar ingin memuji, tapi saya tidak bisa memikirkan kata-kata yang tepat untuk mengatakannya.",
  ui_story_32160601_76_dialog_content = "Kata \"indah\" bahkan tidak cukup untuk menggambarkan perasaan misteri dan penjelajahan langit malam...",
  ui_story_32160601_77_dialog_content = "Itu terdengar seperti cara yang bagus untuk menjelaskannya!",
  ui_story_32160601_78_dialog_content = "Kemarilah.",
  ui_story_32160601_79_dialog_content = "Hah?",
  ui_story_32160601_80_dialog_content = "Cara terbaik untuk melihat bintang adalah sambil berbaring telentang, bukan?",
  ui_story_32160601_81_dialog_content = "K-Kau tidak berpikir ini sedikit terlalu dekat—",
  ui_story_32160601_82_dialog_content = "Bisakah kamu melihat tujuh bintang dari Rasi Bintang Besar?",
  ui_story_32160601_83_dialog_content = "Dibutuhkan satu tahun penuh untuk siklus pegangan sekali dan kembali ke posisi aslinya. Itulah bagaimana kita tahu kapan musim semi telah tiba.",
  ui_story_32160601_84_dialog_content = "Dengan kata lain, Festival Musim Semi?",
  ui_story_32160601_85_dialog_content = "Benar. Siklus baru untuk tahun baru.",
  ui_story_32160601_86_dialog_content = "Itulah sebabnya orang-orang saling memberi hadiah pada hari ini. Ini adalah cara mereka untuk saling berterima kasih atas masa lalu sambil menantikan masa depan yang sejahtera.",
  ui_story_32160601_87_dialog_content = "Aku sudah lama memikirkan hadiah apa yang harus kuberikan untukmu.",
  ui_story_32160601_88_dialog_content = "Sampai hari itu, kamu bilang bintang-bintang jauh lebih jauh dari kita daripada yang kamu pikirkan.",
  ui_story_32160601_89_dialog_content = "... Aku sebenarnya tidak bermaksud apa-apa dengan itu, kamu tahu.",
  ui_story_32160601_90_dialog_content = "Oh, saya mohon berbeda.",
  ui_story_32160601_91_dialog_content = "Mitos penciptaan kami mengatakan bahwa ketika kekacauan pertama kali muncul, yin dan yang terpisah, dan manusia adalah sama-sama tidak berpengetahuan dan tidak beradab.",
  ui_story_32160601_92_dialog_content = "Namun suatu hari, seorang bijak mulai mencari petunjuk dari bintang-bintang. Dengan mengukur dan melacak gerakan mereka, waktu dan tahun ditentukan, dan segalanya menjadi teratur.",
  ui_story_32160601_93_dialog_content = "Bintang-bintang membimbing kita dengan berbagai cara, namun mereka selamanya berada di luar jangkauan kita.",
  ui_story_32160601_94_dialog_content = "Tak peduli seberapa jauh kita mencapai, tak peduli seberapa tinggi kita berdiri, kita tak akan pernah bisa menyentuh mereka.",
  ui_story_32160601_95_dialog_content = "Untuk alasan itu, langit malam selalu menjadi semacam mimpi bagi setiap makhluk hidup.",
  ui_story_32160601_96_dialog_content = "Dan hari ini, akhirnya saya berhasil mendekatkan mimpi itu sedikit lebih dekat dengan kenyataan.",
  ui_story_32160601_97_dialog_content = "PlayerName. Sahabatku.",
  ui_story_32160601_98_dialog_content = "Saya ingin memberikanmu payung besar ini, serta mimpi yang diwakilinya.",
  ui_story_32160601_99_dialog_content = "Apakah itu tanah yang jauh, atau bintang-bintang yang selalu jauh di atas...",
  ui_story_32160601_100_dialog_content = "Saya harap hadiahku mengingatkanmu bahwa tidak ada yang benar-benar di luar jangkauan.",
  ui_story_32160601_101_dialog_content = "Jika suatu hari nanti kamu membutuhkanku, dan aku telah pergi ke suatu tempat yang jauh darimu...",
  ui_story_32160601_102_dialog_content = "Simpan payung ini di sisimu dan kita akan selalu dekat satu sama lain, tidak peduli sejauh apa jaraknya.",
  ui_story_32160601_103_dialog_content = "... Astaga.",
  ui_story_32160601_104_dialog_content = "Aku hanya berharap aku tahu apa yang harus kuberikan sebagai balasan untuk sesuatu yang berharga ini.",
  ui_story_32160601_105_dialog_content = "Hahaha, aku hanya senang kalau kau menyukainya.",
  ui_story_32160601_106_dialog_content = "Mungkin aku tidak tahu jenis penemuan apa yang biasanya dibuat oleh murid-muridmu.",
  ui_story_32160601_107_dialog_content = "Tapi siapa pun akan sangat bangga memiliki payung besar ini. Ini adalah sebuah karya agung yang absolut.",
  ui_story_32160601_108_dialog_content = "Saya setuju denganmu di sana.",
  ui_story_32160601_109_dialog_content = "Ngomong-ngomong, bintang-bintang ini...",
  ui_story_32160601_110_dialog_content = "(Bintang-bintang berkelip-kelip tepat di jangkauan tangan, dan suara lembut roda gigi berputar mencapai telinga kami.)",
  ui_story_32160601_111_dialog_content = "(Di ruang yang tenang itu, Xuan Ji menceritakan semua kisah Longzhou tentang bintang-bintang kepada saya.)",
  ui_story_32160601_112_dialog_content = "(Ini begitu damai sehingga sebelum aku menyadarinya, aku mulai merasa mengantuk.)",
  ui_story_32160601_113_dialog_content = "Merasa lelah? Silakan tidur, jika kamu mau.",
  ui_story_32160601_114_dialog_content = "Jangan khawatir. Tidak ada yang perlu ditakutkan saat kamu berada di bawah payungku.",
  ui_story_32160601_115_dialog_content = "Apakah kita sedang menghadapi badai yang mengaum atau sekumpulan roh jahat, aku akan selalu melindungi sudut kecil dunia ini.",
  ui_story_32160601_116_dialog_content = "Setelah semua, di bawah payung besar ini...",
  ui_story_32160601_117_dialog_content = "Ini adalah pencapaian yang paling saya banggakan di negeri ini."
}
return config
